"""Read integers from numbers.txt, square them in parallel, and print the sum of the even squares."""

from pathlib import Path

import tolquane as tq


@tq.source
def number_lines():
    # Real input source: one integer per line in numbers.txt.
    yield from Path("numbers.txt").read_text().splitlines()


@tq.node
def parse_int(line: str) -> int:
    # Keep parsing separate so tests can feed the same line-shaped stream.
    return int(line.strip())


@tq.node
def square(n: int) -> int:
    # Pure CPU work, so it is the stage that runs on four workers.
    return n * n


@tq.node
def keep_even(square_value: int) -> int:
    # Filter out odd squares; tq.SKIP means no item is sent downstream.
    if square_value % 2 == 0:
        return square_value
    return tq.SKIP


class SumEvenSquares:
    # Stateful accumulator: it emits one total when the input stream ends.
    def __init__(self) -> None:
        self.total = 0

    def __call__(self, square_value: int) -> object:
        self.total += square_value
        return tq.SKIP

    def on_end(self, ctx: tq.Context) -> None:
        ctx.send(self.total)


@tq.sink
def print_total(total: int) -> None:
    # Final sink: print the single sum produced by the accumulator.
    print(total)


def build(source=None):
    start = tq.from_iterable(source) if source is not None else number_lines
    graph = start >> parse_int >> tq.farm(square, workers=4) >> keep_even >> SumEvenSquares >> print_total
    return graph


def main() -> None:
    tq.run(build())


if __name__ == "__main__":
    main()
